public static void registerUseAbilityPacketHandler() {
        NetworkManager.registerReceiver(NetworkManager.Side.C2S, USE_ABILITY, (buf, context) -> {
            PlayerEntity player = context.getPlayer();

            context.getPlayer().getServer().execute(() -> {
                LivingEntity identity = PlayerIdentity.getIdentity(player);

                // Verify we should use ability for the player's current identity
                if(identity != null) {
                    EntityType<?> identityType = identity.getType();

                    if(AbilityRegistry.has(identityType)) {

                        // Check cooldown
                        if(PlayerAbilities.canUseAbility(player)) {
                            AbilityRegistry.get(identityType).onUse(player, identity, context.getPlayer().getWorld());
                            PlayerAbilities.setCooldown(player, AbilityRegistry.get(identityType).getCooldown(identity));
                            PlayerAbilities.sync((ServerPlayerEntity) player);
                        }
                    }
                }
            });
        });
    }

public static void sendFavoriteRequest(IdentityType<?> type, boolean favorite) {
        PacketByteBuf packet = new PacketByteBuf(Unpooled.buffer());
        packet.writeIdentifier(Registries.ENTITY_TYPE.getId(type.getEntityType()));
        packet.writeInt(type.getVariantData());
        packet.writeBoolean(favorite);
        NetworkManager.sendToServer(ClientNetworking.FAVORITE_UPDATE, packet);
    }

public static void registerFavoriteRequestHandler() {
        NetworkManager.registerReceiver(NetworkManager.Side.C2S, NetworkHandler.FAVORITE_UPDATE, (buf, context) -> {
            EntityType<?> entityType = Registries.ENTITY_TYPE.get(buf.readIdentifier());
            int variant = buf.readInt();
            boolean favorite = buf.readBoolean();
            ServerPlayerEntity player = (ServerPlayerEntity) context.getPlayer();

            context.getPlayer().getServer().execute(() -> {
                @Nullable IdentityType<?> type = IdentityType.from(entityType, variant);

                if(type != null) {
                    if(favorite) {
                        PlayerFavorites.favorite(player, type);
                    } else {
                        PlayerFavorites.unfavorite(player, type);
                    }
                }
            });
        });
    }

public static void sendFavoriteSync(ServerPlayerEntity player) {
        Set<IdentityType<?>> favorites = ((PlayerDataProvider) player).getFavorites();
        NbtCompound tag = new NbtCompound();
        NbtList idList = new NbtList();
        favorites.forEach(type -> idList.add(type.writeCompound()));
        tag.put("FavoriteIdentities", idList);

        // Create & send packet with NBT
        PacketByteBuf packet = new PacketByteBuf(Unpooled.buffer());
        packet.writeNbt(tag);
        NetworkManager.sendToPlayer(player, NetworkHandler.FAVORITE_SYNC, packet);
    }

public static void handleFavoriteSyncPacket(PacketByteBuf packet, NetworkManager.PacketContext context) {
        NbtCompound tag = packet.readNbt();

        ClientNetworking.runOrQueue(context, player -> {
            PlayerDataProvider data = (PlayerDataProvider) player;
            data.getFavorites().clear();
            NbtList idList = tag.getList("FavoriteIdentities", NbtElement.COMPOUND_TYPE);
            idList.forEach(compound -> data.getFavorites().add(IdentityType.from((NbtCompound) compound)));
        });
    }

public static void registerIdentityRequestPacketHandler() {
        NetworkManager.registerReceiver(NetworkManager.Side.C2S, NetworkHandler.IDENTITY_REQUEST, (buf, context) -> {
            boolean validType = buf.readBoolean();
            if(validType) {
                EntityType<?> entityType = Registries.ENTITY_TYPE.get(buf.readIdentifier());
                int variant = buf.readInt();

                context.getPlayer().getServer().execute(() -> {
                    // Ensure player has permission to switch identities
                    if(IdentityConfig.getInstance().enableSwaps() || context.getPlayer().hasPermissionLevel(3)) {
                        // player type shouldn't be sent, but we still check regardless
                        if(entityType.equals(EntityType.PLAYER)) {
                            PlayerIdentity.updateIdentity((ServerPlayerEntity) context.getPlayer(), null, null);
                        } else {
                            @Nullable IdentityType<LivingEntity> type = IdentityType.from(entityType, variant);
                            if(type != null) {
                                PlayerIdentity.updateIdentity((ServerPlayerEntity) context.getPlayer(), type, type.create(context.getPlayer().getWorld()));
                            }
                        }

                        // Refresh player dimensions
                        context.getPlayer().calculateDimensions();
                    }
                });
            } else {
                // Swap back to player if server allows it
                context.getPlayer().getServer().execute(() -> {
                    if(IdentityConfig.getInstance().enableSwaps() || context.getPlayer().hasPermissionLevel(3)) {
                        PlayerIdentity.updateIdentity((ServerPlayerEntity) context.getPlayer(), null, null);
                    }

                    context.getPlayer().calculateDimensions();
                });
            }
        });
    }

public static void sendSwapRequest(@Nullable IdentityType<?> type) {
        PacketByteBuf packet = new PacketByteBuf(Unpooled.buffer());

        packet.writeBoolean(type != null);
        if(type != null) {
            packet.writeIdentifier(Registries.ENTITY_TYPE.getId(type.getEntityType()));
            packet.writeInt(type.getVariantData());
        }

        NetworkManager.sendToServer(ClientNetworking.IDENTITY_REQUEST, packet);
    }

public static void handleUnlockSyncPacket(PacketByteBuf packet, NetworkManager.PacketContext context) {
        NbtCompound nbt = packet.readNbt();
        if(nbt != null) {
            NbtList list = nbt.getList(UNLOCK_KEY, NbtElement.COMPOUND_TYPE);

            ClientNetworking.runOrQueue(context, player -> {
                ((PlayerDataProvider) player).getUnlocked().clear();
                list.forEach(idTag -> ((PlayerDataProvider) player).getUnlocked().add(IdentityType.from((NbtCompound) idTag)));
            });
        }
    }

public static void sendSyncPacket(ServerPlayerEntity player) {
        PacketByteBuf packet = new PacketByteBuf(Unpooled.buffer());

        // Serialize unlocked to tag
        NbtCompound compound = new NbtCompound();
        NbtList idList = new NbtList();
        ((PlayerDataProvider) player).getUnlocked().forEach(type -> idList.add(type.writeCompound()));
        compound.put(UNLOCK_KEY, idList);
        packet.writeNbt(compound);

        // Send to client
        NetworkManager.sendToPlayer(player, NetworkHandler.UNLOCK_SYNC, packet);
    }

